package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextRelationalInterpretation.*;
import org.kanger.ContextWitnessResultTransport.*;
import org.kanger.ContextSignedRelationalModelSearch.*;
final class ContextRankBudgetMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static List<String> vars(int n){return ContextGeneralArgumentsMatrix.variables(n);}
 static String atom(String name,List<String> args){return ContextGeneralArgumentsMatrix.atom(name,args);}
 static String existential(int n){StringBuilder b=new StringBuilder("!");for(String s:vars(n))b.append('$').append(s).append(' ');return b+atom("wide",vars(n))+";";}
 static Snapshot bind(boolean x,String s)throws Exception{return ContextRelationalModelMatrix.bind(x,s);}
 static Map<String,Integer> bounds(int rank,int witnesses,int origins){Map<String,Integer> b=new LinkedHashMap<>();b.put("rank",rank);b.put("witnesses",witnesses);b.put("origins",origins);b.put("rounds",4);return b;}
 static ContextSignedModelEvaluation.Result run(Snapshot x,List<Snapshot> f,Map<String,Integer>b){return ContextSignedModelEvaluation.runAutomatic(x,f,new ContextSignedModelRequest("!p(1);",b).policy);}
 static ContextSignedModelEvaluation.Result model(Snapshot x,List<Snapshot> f,Map<String,Integer>b){ContextSignedModelEvaluation.Result r=run(x,f,b);require(r.status==ContextSignedModelInspection.Status.MODELLED_SUPPLIED&&r.relational!=null,r.phase+": "+r.reason);ContextSignedRelationalModelAudit.check(r.relational.output,WORK);require(true,"independent original and actual-final rank receipts");return r;}
 static void positive()throws Exception{
  for(int n:new int[]{5,9,17,65,257}){Snapshot x=bind(true,existential(n));ContextSignedModelEvaluation.Result r=model(x,Collections.emptyList(),bounds(n,n,0));ContextRelationalInterpretation m=r.relational.output.ledger.models.get(Cut.of(x));require(m.witnesses.size()==n&&m.denotations.size()==n&&m.witnesses.values().stream().allMatch(i->i==0),"all "+n+" declared/actual Origins retained with coincident one-point interpretation");require(m.relations.containsKey(new Signature("wide",n)),"exact unbounded arity and existential rank "+n);}
  int n=17;List<String> v=vars(n),back=new ArrayList<>(v);Collections.reverse(back);Snapshot x=bind(true,existential(n)+ContextGeneralArgumentsMatrix.prefix(v)+atom("wide",v)+"->"+atom("out",back)+";");ContextSignedModelEvaluation.Result r=model(x,Collections.emptyList(),bounds(n,n,0));boolean actual=false;for(Obligation o:r.relational.output.ledger.obligations){List<Origin> os=ContextMultiOriginMatrix.origins(o,"out");if(os!=null&&os.size()==n){boolean exact=true;for(int i=0;i<n;i++)exact&=os.get(i)!=null&&os.get(i).binder==n-1-i;if(exact)actual=true;}}require(actual,"derived reversed17-Origin tuple preserves every coordinate, not merely first8");
  n=65;v=vars(n);List<String> reversed=new ArrayList<>(v);Collections.reverse(reversed);StringBuilder prefix=new StringBuilder("!");for(String s:v)prefix.append('$').append(s).append(' ');Snapshot opposite=bind(true,prefix+atom("wide",v)+"&&~"+atom("wide",reversed)+";");r=model(opposite,Collections.emptyList(),bounds(n,n,0));ContextRelationalInterpretation m=r.relational.output.ledger.models.get(Cut.of(opposite));require(r.namedPoints==2&&new HashSet<>(m.witnesses.values()).size()==2,"65-Origin asymmetric relation can identify most binders yet requires two actual values");
 }
 static void integrity()throws Exception{
  int n=65;Snapshot x=bind(true,existential(n));ContextSignedModelEvaluation.Result r=model(x,Collections.emptyList(),bounds(n,n,0));Ledger good=r.relational.output.ledger;ContextRelationalInterpretation m=good.models.get(Cut.of(x));Source s=x.primary.get(0).source;Map<Binder,Integer> missing=new LinkedHashMap<>(m.witnesses);missing.remove(new Binder(s,64));require(!ContextRelationalModelMatrix.originalAccepts(ContextMultiBinderModelMatrix.replace(good,x,new ContextRelationalInterpretation(m.points,m.relations,missing,m.denotations))),"65th original binder cannot disappear behind old64-entry capacity");
  Map<Origin,Integer> finalMissing=new LinkedHashMap<>(m.denotations);finalMissing.keySet().removeIf(o->o.binder==64);require(!ContextMultiBinderModelMatrix.finalAccepts(ContextMultiBinderModelMatrix.replace(good,x,new ContextRelationalInterpretation(m.points,m.relations,m.witnesses,finalMissing))),"65th actual final Origin independently required");
  ContextSignedUnaryModelSearch.Policy p=good.policy;ContextSignedUnaryModelSearch.Policy low=new ContextSignedUnaryModelSearch.Policy(p.candidates,p.cells,64,p.work,p.original,p.extension);require(!ContextRelationalModelMatrix.originalAccepts(new Ledger(good.branch,low,good.models,good.rows,good.obligations)),"independent original audit enforces configured witness64 against actual65");
  SignedSeedFrame frame=r.branch.seeds.frame;ContextSignedWitnessFrameMatrix.mutate(frame,"maximumRank",64,()->require(!ContextSignedWitnessFrameAudit.inspect(frame,frame.plan,x,Collections.emptyList(),64,64,WORK,WORK).audited,"independent frame audit counts all65 even when claimed policy metadata lowered to64"));
  boolean legacy=false;try{ContextSignedWitnessInitialBarrierAudit.union(frame.common,Collections.singletonList(frame.common),ContextGroundProductionRounds.budget(WORK),16);}catch(IllegalStateException expected){legacy=true;}require(legacy,"legacy four-argument barrier audit keeps its original rank8 policy");ContextSignedWitnessInitialBarrierAudit.union(frame.common,Collections.singletonList(frame.common),ContextGroundProductionRounds.budget(WORK),16,n);require(true,"explicit requested rank reaches independent barrier audit");
  require(run(x,Collections.emptyList(),bounds(64,n,0)).status==ContextSignedModelInspection.Status.INCOMPLETE,"rank budget stop is incomplete, not a contradiction");require(run(x,Collections.emptyList(),bounds(n,64,0)).status==ContextSignedModelInspection.Status.INCOMPLETE,"witness choice budget independently stops before successful model");
 }
 static void topology()throws Exception{
  int n=17;List<String> v=vars(n),back=new ArrayList<>(v);Collections.reverse(back);Snapshot x=bind(true,ContextGeneralArgumentsMatrix.prefix(v)+atom("wide",v)+"->"+atom("out",back)+";"),a=bind(false,existential(n));ContextSignedModelEvaluation.Result r=model(x,Collections.singletonList(a),bounds(n,n,n));Ledger good=r.relational.output.ledger;require(good.models.get(Cut.of(x)).witnesses.isEmpty()&&good.models.get(Cut.of(x)).denotations.size()==n,"17 foreign Origins imported through X-dependent product, never original X facts");require(run(x,Collections.singletonList(a),bounds(n,n,n-1)).status==ContextSignedModelInspection.Status.INCOMPLETE,"separate imported-Origin budget has no hidden8 ceiling and stops at requested16");
  ContextSignedUnaryModelSearch.Policy p=good.policy;ContextSignedUnaryExtensionSearch.Policy ext=new ContextSignedUnaryExtensionSearch.Policy(p.extension.candidates,p.extension.cells,n-1,p.extension.work,p.extension.audit);ContextSignedUnaryModelSearch.Policy policy=new ContextSignedUnaryModelSearch.Policy(p.candidates,p.cells,p.witnesses,p.work,p.original,ext);Ledger low=new Ledger(good.branch,policy,good.models,good.rows,good.obligations);require(ContextRelationalModelMatrix.originalAccepts(low)&&!ContextMultiBinderModelMatrix.finalAccepts(low),"independent final audit enforces imported rank without invalidating original truth");
  Snapshot root=bind(true,"!anchor(1);"),b=bind(false,ContextGeneralArgumentsMatrix.prefix(v)+"~"+atom("wide",v)+";");for(boolean reverse:new boolean[]{false,true}){r=model(root,reverse?Arrays.asList(b,a):Arrays.asList(a,b),bounds(n,n,0));require(r.branch.termination.result.output.current().packet.items.stream().noneMatch(i->i.atom.predicate.equals("wide")),"17-Origin raw private seed stays outside common X in either order");}
  Snapshot trust=ContextProductionNativeBinding.trusted("rank17",Arrays.asList(a,b),WORK);require(run(root,Collections.singletonList(trust),bounds(n,0,0)).status==ContextSignedModelInspection.Status.REFUTED,"whole TRUST refutation precedes zero witness/imported model budgets");
 }
}
